jdoe -Properties LockedOut,PasswordLastSet","screen":"","result":"Verified by the simulation state."},{"title":"Test simulated login","desc":"Training environment with fictional domain account jdoe. No real account is changed.","type":"checkpoint","actionId":"account.test-login","expectedCommands":[],"action":"Use the checkpoint button.","screen":"","result":"Verified by the simulation state."}]}'::jsonb
WHERE "id" = 'account-lockout-resolution' AND NOT EXISTS (
